CREATE TABLE "competition_application" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "event_id" bigint NOT NULL,
    "athlete_user_id" bigint NOT NULL,
    "submitted_by_user_id" bigint NOT NULL,
    "status" varchar(20) NOT NULL DEFAULT 'pending',
    "submitted_at" timestamptz NOT NULL DEFAULT now(),
    "reviewed_by_user_id" bigint,
    "reviewed_at" timestamptz,
    CONSTRAINT "competition_application_event_id_fkey"
        FOREIGN KEY ("event_id") REFERENCES "competition_event" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_application_athlete_user_id_fkey"
        FOREIGN KEY ("athlete_user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_application_submitted_by_user_id_fkey"
        FOREIGN KEY ("submitted_by_user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT "competition_application_reviewed_by_user_id_fkey"
        FOREIGN KEY ("reviewed_by_user_id") REFERENCES "user" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

CREATE TABLE "competition_result" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "application_id" bigint UNIQUE NOT NULL,
    "place" integer,
    "score" numeric(12,2),
    "result_status" varchar(30),
    CONSTRAINT "competition_result_application_id_fkey"
        FOREIGN KEY ("application_id") REFERENCES "competition_application" ("id") DEFERRABLE INITIALLY IMMEDIATE
);

ALTER TABLE "user_rank_discipline"
    ADD CONSTRAINT "user_rank_discipline_result_id_fkey"
    FOREIGN KEY ("result_id") REFERENCES "competition_result" ("id") DEFERRABLE INITIALLY IMMEDIATE;

CREATE UNIQUE INDEX "competition_application_event_id_athlete_user_id_idx"
    ON "competition_application" ("event_id", "athlete_user_id");

COMMENT ON COLUMN "competition_application"."submitted_by_user_id" IS 'Сам спортсмен или его тренер';
COMMENT ON COLUMN "competition_application"."status" IS 'pending, approved, rejected, withdrawn';
COMMENT ON COLUMN "competition_result"."result_status" IS 'finished, did_not_start, disqualified';
